import React from 'react';

const PredictionResult = ({ result }) => {
  const getPredictionStyle = (label) => {
    switch (label?.toLowerCase()) {
      case 'good': return { backgroundColor: '#4caf50', color: '#fff' };
      case 'moderate': return { backgroundColor: '#ffeb3b', color: '#000' };
      case 'poor': return { backgroundColor: '#ff9800', color: '#fff' };
      case 'unhealthy': return { backgroundColor: '#f44336', color: '#fff' };
      case 'hazardous': return { backgroundColor: '#b71c1c', color: '#fff' };
      default: return { backgroundColor: '#9e9e9e', color: '#fff' };
    }
  };

  if (!result) return null;

  return (
    <div style={{ marginTop: '20px', padding: '15px', borderRadius: '8px', textAlign: 'center', fontSize: '20px', ...getPredictionStyle(result) }}>
      {result.toUpperCase()}
    </div>
  );
};

export default PredictionResult;
